public class ResetMultiwayOracle {
 static client c=new client();static DataOutputStream out;static int resetCases,images;
 static boolean present(int slot,int seed,int last){return slot==0 || slot==last || (slot+seed)%(seed==0?1:seed%37+1)==0;}
 static void init(PathingEntity e,int slot,int seed){e.primarySeqId=(slot+seed)%511;e.primarySeqFrame=slot%17;e.primarySeqCycle=seed%13;e.primarySeqDelay=seed%7;e.primarySeqLoop=slot%5;e.secondarySeqId=-1;e.secondarySeqFrame=slot%9;e.secondarySeqCycle=seed%11;}
 static void actor(PathingEntity e)throws Exception{out.writeBoolean(e!=null);if(e!=null)for(int v:new int[]{e.primarySeqId,e.primarySeqFrame,e.primarySeqCycle,e.primarySeqDelay,e.primarySeqLoop,e.secondarySeqId,e.secondarySeqFrame,e.secondarySeqCycle})out.writeInt(v);}
 static void read(int op,byte[] payload)throws Exception{byte[] frame=new byte[1+payload.length];frame[0]=(byte)op;System.arraycopy(payload,0,frame,1,payload.length);final ByteArrayInputStream input=new ByteArrayInputStream(frame);Socket socket=new Socket(){public void setSoTimeout(int n){}public void setTcpNoDelay(boolean b){}public InputStream getInputStream(){return input;}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}};c.stream=new ClientStream(c,(byte)2,socket);c.randomIn=null;c.packetType=-1;if(!c.read(false)||input.available()!=0||c.packetType!=-1)throw new Exception("read failed");}
 static void indicator(int x,int z,int flag)throws Exception{out.writeInt(x);out.writeInt(z);out.writeInt(flag);c.sceneBaseTileX=c.sceneBaseTileZ=0;c.localPlayer.x=x*128;c.localPlayer.z=z*128;read(254,new byte[]{(byte)flag});int[] pixels=new int[512*334];Pix2D.bind(512,pixels,-657,334);c.draw3DEntityElements(9);out.writeInt(c.inMultizone);out.writeInt(c.wildernessLevel);out.writeInt(c.worldLocationState);int y=c.wildernessLevel>0||c.worldLocationState==1?258:296;out.writeInt(y);int count=0;for(int row=0;row<32;row++)for(int col=0;col<40;col++)if(pixels[(y+row)*512+472+col]!=0)count++;out.writeInt(count);for(int row=0;row<32;row++)for(int col=0;col<40;col++){int pixel=pixels[(y+row)*512+472+col];if(pixel!=0){out.writeInt(row*40+col);out.writeInt(pixel);}}images++;}
 public static void main(String[] args)throws Exception{
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();out=new DataOutputStream(new BufferedOutputStream(bytes));for(int seed=0;seed<128;seed++){Arrays.fill(c.players,null);Arrays.fill(c.npcs,null);out.writeInt(seed);for(int i=0;i<2048;i++)if(present(i,seed,2047)){c.players[i]=new PlayerEntity();init(c.players[i],i,seed);}for(int i=0;i<8192;i++)if(present(i,seed,8191)){c.npcs[i]=new NpcEntity();init(c.npcs[i],i,seed);}c.localPlayer=c.players[2047];c.playerCount=c.npcCount=0;read(136,new byte[0]);for(PlayerEntity e:c.players)actor(e);for(NpcEntity e:c.npcs)actor(e);resetCases++;}out.flush();try(DataOutputStream f=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(args[1])))){f.writeInt(0x524d3235);f.writeInt(resetCases);f.write(bytes.toByteArray());}
  Arrays.fill(c.players,null);Arrays.fill(c.npcs,null);c.playerCount=c.npcCount=0;c.localPlayer=new PlayerEntity();c.localPlayer.visible=false;Jagfile media=new Jagfile(Files.readAllBytes(Paths.get(args[0],"media")),false),title=new Jagfile(Files.readAllBytes(Paths.get(args[0],"title")),false);for(int i=0;i<7;i++)c.imageHeadicons[i]=new Pix32(media,"headicons",i);c.fontPlain12=new PixFont(title,"p12",530);c.viewportInterfaceId=-1;c.menuVisible=false;c.menuSize=1;c.mouseX=c.mouseY=0;
  bytes=new ByteArrayOutputStream();out=new DataOutputStream(new BufferedOutputStream(bytes));for(int flag=0;flag<256;flag++)for(int[] p:new int[][]{{3200,3200},{3100,3600},{3100,10000},{3332,3244},{3358,3244},{3392,3264}})indicator(p[0],p[1],flag);for(int x=3328;x<3392;x++)for(int z=3200;z<3264;z++)indicator(x,z,1);for(int x:new int[]{2943,2944,3391,3392})for(int z:new int[]{3519,3520,6399,6400,9919,9920,12799,12800})for(int flag:new int[]{0,1})indicator(x,z,flag);
  out.flush();try(DataOutputStream f=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(args[2])))){f.writeInt(0x4d553235);f.writeInt(images);f.write(bytes.toByteArray());}System.out.println("Original reset:"+resetCases+" full2048/8192 sparse/dense arrays,all cached inactive slots and8 animation fields;multiway:"+images+" packet254/draw3DEntityElements icon regions40x32,all byte flags/arena64x64/wilderness boundaries");
 }
}
